import{_ as r,o as n,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Recherche: Die Causa „Postenschacher“ (August Wöginger)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/postenschacher-woeginger.md","filePath":"recherche/postenschacher-woeginger.md"}'),a={name:"recherche/postenschacher-woeginger.md"};function s(u,e,h,g,l,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-causa-„postenschacher-august-woginger" tabindex="-1">Recherche: Die Causa „Postenschacher“ (August Wöginger) <a class="header-anchor" href="#recherche-die-causa-„postenschacher-august-woginger" aria-label="Permalink to &quot;Recherche: Die Causa „Postenschacher“ (August Wöginger)&quot;">​</a></h1><p><strong>Der Fall des Klubobmanns: Wenn politische Intervention auf Amtsmissbrauch trifft.</strong></p><p>Parallel zu den historischen Machenschaften der Ära Horten bietet die aktuelle politische Landschaft Österreichs reichlich Stoff für unsere Mockumentary. Ein Paradebeispiel für moderne Interventionen ist der Prozess gegen ÖVP-Klubobmann <strong>August Wöginger</strong>, der sich aktuell (Stand Februar/März 2026) vor dem Landesgericht Linz verantworten muss.</p><hr><h2 id="der-vorwurf-bestimmung-zum-amtsmissbrauch" tabindex="-1">Der Vorwurf: Bestimmung zum Amtsmissbrauch <a class="header-anchor" href="#der-vorwurf-bestimmung-zum-amtsmissbrauch" aria-label="Permalink to &quot;Der Vorwurf: Bestimmung zum Amtsmissbrauch&quot;">​</a></h2><p>Die Wirtschafts- und Korruptionsstaatsanwaltschaft (WKStA) wirft August Wöginger vor, im Jahr 2017 bei <strong>Thomas Schmid</strong> (damals Generalsekretär im Finanzministerium) interveniert zu haben.</p><ul><li><strong>Das Ziel:</strong> Einem ÖVP-Bürgermeister aus dem Bezirk Schärding sollte der Posten als Leiter des Finanzamts Braunau-Ried-Schärding verschafft werden.</li><li><strong>Die Problematik:</strong> Eine andere Bewerberin, Christa Scharf, galt laut Bundesverwaltungsgericht als fachlich besser qualifiziert. Sie wurde jedoch übergangen.</li><li><strong>Die Rolle Wögingers:</strong> Er wird als „Bestimmungstäter“ geführt, da er die Entscheidungsträger zur unrechtmäßigen Besetzung angestiftet haben soll.</li></ul><hr><h2 id="aktueller-stand-der-gerichtsverhandlung-marz-2026" tabindex="-1">Aktueller Stand der Gerichtsverhandlung (März 2026) <a class="header-anchor" href="#aktueller-stand-der-gerichtsverhandlung-marz-2026" aria-label="Permalink to &quot;Aktueller Stand der Gerichtsverhandlung (März 2026)&quot;">​</a></h2><p>Nachdem eine ursprünglich geplante Diversion (Zahlung einer Geldbuße ohne Schuldeingeständnis) durch das Oberlandesgericht Linz aufgehoben wurde, läuft nun die Hauptverhandlung.</p><h3 id="_1-einvernahmen-der-mitangeklagten-februar-2026" tabindex="-1">1. Einvernahmen der Mitangeklagten (Februar 2026) <a class="header-anchor" href="#_1-einvernahmen-der-mitangeklagten-februar-2026" aria-label="Permalink to &quot;1. Einvernahmen der Mitangeklagten (Februar 2026)&quot;">​</a></h3><p>Die zwei mitangeklagten Finanzbeamten wurden getrennt befragt:</p><ul><li><strong>Der Kommissionsvorsitzende (Siegfried M.):</strong> Bekennt sich „nicht schuldig“.</li><li><strong>Der Personalvertreter (Herbert B.):</strong> Gab zu, dass Thomas Schmid ihn gebeten habe, den Bürgermeister zu unterstützen, bestreitet aber Manipulationen. Er bezeichnete Schmids Aussagen am 3. März als „Lüge“.</li></ul><h3 id="_2-einvernahme-august-woginger-3-marz-2026" tabindex="-1">2. Einvernahme August Wöginger (3. März 2026) <a class="header-anchor" href="#_2-einvernahme-august-woginger-3-marz-2026" aria-label="Permalink to &quot;2. Einvernahme August Wöginger (3. März 2026)&quot;">​</a></h3><p>Am heutigen Tag stand der Klubobmann selbst im Zeugenstand:</p><ul><li><strong>Plädoyer:</strong> „Nicht schuldig“. Wöginger betonte, die erste Diversion sei kein Schuldeingeständnis gewesen, sondern ein Versuch, das Verfahren zum Schutz seiner Familie schnell zu beenden.</li><li><strong>Zentrale Aussage:</strong> „Ich würde es heute nicht mehr tun.“ Er räumte Reue über die Weiterleitung der Bewerbung ein („Es tut mir leid, was meine Bitte um Prüfung ausgelöst hat“), bestreitet aber jede Anstiftung zum Amtsmissbrauch. Es habe sich lediglich um ein „Bürgeranliegen“ gehandelt.</li></ul><h3 id="_3-der-weitere-fahrplan" tabindex="-1">3. Der weitere Fahrplan <a class="header-anchor" href="#_3-der-weitere-fahrplan" aria-label="Permalink to &quot;3. Der weitere Fahrplan&quot;">​</a></h3><ul><li><strong>5. März 2026:</strong> Befragung der übergangenen Mitbewerberin Christa Scharf.</li><li><strong>9. März 2026:</strong> Erwartete Aussage von Kronzeuge <strong>Thomas Schmid</strong>.</li><li><strong>21. April 2026:</strong> Angestrebtes Urteil.</li></ul><h3 id="_4-ziviler-widerstand-satire-3-marz-2026" tabindex="-1">4. Ziviler Widerstand &amp; Satire (3. März 2026) <a class="header-anchor" href="#_4-ziviler-widerstand-satire-3-marz-2026" aria-label="Permalink to &quot;4. Ziviler Widerstand &amp; Satire (3. März 2026)&quot;">​</a></h3><p>Vor dem Gerichtsgebäude in Linz sorgt ein Demonstrant (Andreas Röbl) mit einem großen Plakat für Aufsehen:</p><ul><li><strong>Motto:</strong> „Oh du liaba Augustin“ – in Anlehnung an das bekannte Volkslied, aber gemünzt auf den Klubobmann.</li><li><strong>Botschaft:</strong> Der Protest richtet sich gegen das System des Postenschachers, das als „österreichische Krankheit“ bezeichnet wird.</li><li><strong>Symbolik:</strong> Für den Demonstranten ist nicht der Politiker, sondern die übergangene Beamtin Christa Scharf die eigentliche Heldin, da sie sich gegen die Übermacht der Strukturen wehrte.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>In unserer Mockumentary ziehen wir Parallelen zwischen der historischen Begünstigung von „Freunden“ (wie Helmut Horten durch das NS-Regime) und dem modernen Postenschacher.</p><ul><li><strong>Das Motiv der „Intervention“:</strong> Es zeigt, dass Macht nicht nur durch Geld (Spenden), sondern auch durch den Zugriff auf staatliche Strukturen (Postenbesetzungen) gefestigt wird.</li><li><strong>Satirische Umsetzung:</strong> Wir planen eine Szene, in der ein fiktiver Politiker versucht, eine Intervention als „regionale Strukturförderung“ umzudeuten – ganz im Stil von Wögingers Verteidigungslinie.</li></ul><hr><hr><h2 id="die-anzeige-von-sebastian-kurz-april-2026" tabindex="-1">Die Anzeige von Sebastian Kurz (April 2026) <a class="header-anchor" href="#die-anzeige-von-sebastian-kurz-april-2026" aria-label="Permalink to &quot;Die Anzeige von Sebastian Kurz (April 2026)&quot;">​</a></h2><p>Im April 2026 hat Sebastian Kurz (vertreten durch Anwalt Werner Suppan) eine Anzeige wegen Falschaussage gegen Thomas Schmid eingebracht.</p><ul><li><strong>Der Vorwurf:</strong> Schmid habe im Prozess rund um August Wöginger (Finanzamt Braunau/Freistadt) vor dem Landesgericht Linz gelogen.</li><li><strong>Strategisches Ziel:</strong> Die Glaubwürdigkeit des Kronzeugen Schmid soll systematisch untergraben werden.</li><li><strong>Verbindung zur Inseraten-Causa:</strong> Diese Anzeige ist Teil einer breit angelegten Zangenbewegung der ÖVP-nahen Verteidigungsteams. Während Michael Rami in der Inseraten-Causa auf statistische „Säuberung“ (WU-Studie) setzt, nutzt Suppan im Postenschacher-Fall die strafrechtliche Keule.</li></ul><p>In der Mockumentary nutzen wir dies als Beispiel für die <strong>„Juristische Hydra“</strong>: Schlägt man einen Kopf ab (oder taucht ein Belastungszeuge auf), wachsen zwei neue Klagen nach, um die Wahrheit im Keim zu ersticken.</p><p><em>Stand der Recherche: 07. April 2026.</em></p>',32)])])}const m=r(a,[["render",s]]);export{c as __pageData,m as default};
